/*
 * Site-wide Twitch live indicator.
 * Fetches assets/data/stream_status.json (generated by fetch_stream_status.py
 * via the scheduled check_live_status workflow) and lights up the navbar dot
 * when the channel is live. Data older than 24h is ignored.
 */
(function () {
    'use strict';

    var DOT_ID = 'live-status-dot';
    var STATUS_URL = '/assets/data/stream_status.json';
    var STALE_AFTER_MS = 24 * 60 * 60 * 1000;

    function init() {
        var dot = document.getElementById(DOT_ID);
        if (!dot || dot.dataset.loaded === 'true') return;
        dot.dataset.loaded = 'true';

        fetch(STATUS_URL)
            .then(function (response) {
                if (!response.ok) throw new Error('HTTP ' + response.status);
                return response.json();
            })
            .then(function (status) {
                var fresh = status &&
                    typeof status.isLive === 'boolean' &&
                    status.checkedAt &&
                    (Date.now() - Date.parse(status.checkedAt)) < STALE_AFTER_MS;

                if (fresh && status.isLive) {
                    dot.hidden = false;
                    dot.title = 'Live now on Twitch';
                    var link = dot.closest('a');
                    if (link) {
                        var label = link.querySelector('.navbar-label');
                        if (label && !label.textContent.trim()) {
                            label.textContent = ' (live)';
                        }
                    }
                }
                // Offline, stale, or missing: the dot simply stays hidden
            })
            .catch(function () {
                // No status data: leave the dot hidden
            });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
